contract InvMutTest {
    C c;
    uint threshold;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint _threshold) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(_threshold > 0);
        threshold = _threshold;
        uint balCBefore = address(c).balance;
        uint balThisBefore = address(this).balance;
        bool reverted;
        c.withdrawAll(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }   // boundary
        assert(reverted || (address(this).balance == balThisBefore + balCBefore));
    }
    receive() external payable {
        if (msg.value >= threshold) revert();
    }
    fallback() external payable {
        if (msg.value >= threshold) revert();
    }
}

