// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;
    uint threshold;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(uint256 _threshold) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_threshold > 0);
        threshold = _threshold;
        uint balCBefore = address(c).balance;
        uint balThisBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll(address(this)) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted || (address(this).balance == balThisBefore + balCBefore));
    }

    function testFuzz_run(uint256 _threshold) public {
        _run(_threshold);
    }

    receive() external payable {
        if (msg.value >= threshold) revert();
    }

    fallback() external payable {
        if (msg.value >= threshold) revert();
    }
}
